    }
}
</code></pre> <p>A dashboard with only static sections is declared the same way: you can ignore the returned handle.</p> <pre><code>Flocon.dashboardPlugin.dashboard(id: "main") {
    FloconSection("App Status") {
        FloconText("Environment", "Staging")
        FloconButton("Clear Image Cache", id: "clear_cache") { clearImageCache() }
    }
}
</code></pre> <pre><code>Flocon.dashboard.dashboard('main', [
  FloconSection('App Status', [
    FloconText('Environment', 'Staging'),
    FloconButton('Clear Image Cache', id: 'clear_cache', onClick: clearImageCache),
  ]),
]);
</code></pre>

KotlinSwiftFlutter <p>Add the database core and the module matching your library (debug real module, release <code>-no-op</code>). Replace <code>LAST_VERSION</code> with the latest release, or use the BOM described in Kotlin SDK:</p> Room 2 (androidx.room)Room 3 (androidx.room3)SQLDelight 2 <pre><code>dependencies {
    debugImplementation("io.github.openflocon:flocon-database-core:LAST_VERSION")
    debugImplementation("io.github.openflocon:flocon-database-room:LAST_VERSION")
    releaseImplementation("io.github.openflocon:flocon-database-core-no-op:LAST_VERSION")
    releaseImplementation("io.github.openflocon:flocon-database-room-no-op:LAST_VERSION")
}
</code></pre> <pre><code>dependencies {
    debugImplementation("io.github.openflocon:flocon-database-core:LAST_VERSION")
    debugImplementation("io.github.openflocon:flocon-database-room3:LAST_VERSION")
    releaseImplementation("io.github.openflocon:flocon-database-core-no-op:LAST_VERSION")
    releaseImplementation("io.github.openflocon:flocon-database-room3-no-op:LAST_VERSION")
}
</code></pre> <pre><code>dependencies {
    debugImplementation("io.github.openflocon:flocon-database-sqldelight:LAST_VERSION")
    releaseImplementation("io.github.openflocon:flocon-database-sqldelight-no-op:LAST_VERSION")
}
</code></pre> <p><code>flocon-database-core</code> (and <code>-no-op</code> for release) comes with it.</p> <p>For Room, install the plugin. <code>room()</code> (from <code>io.github.openflocon.flocon.database.room</code>, or <code>.room3</code>) adds the Room provider:</p> <pre><code>startFlocon(FloconContext(context)) {
    install(FloconDatabase) {
        room()
    }
}
</code></pre> <p>For SQLDelight, or when you only register databases by hand, <code>install(FloconDatabase)</code> is enough.</p> <p>The database feature is part of the <code>Flocon</code> product, there is nothing else to add. Install it with <code>.database</code>:</p> <pre><code>import Flocon

#if DEBUG
startFlocon { flocon in
    flocon.install(.database)
}
#endif
</code></pre> <p>The SQLite files of <code>Documents</code> and <code>Library/Application Support</code> are listed without any registration, so Core Data stores, GRDB and SQLite.swift databases usually show up right away.</p> <pre><code>flutter pub add flocon flocon_database
</code></pre> <pre><code>import 'package:flocon/flocon.dart';
import 'package:flocon_database/flocon_database.dart';

await startFlocon((flocon) =&gt; flocon..install(const FloconDatabase()));
</code></pre> <p>The SQLite files of the databases folder (<code>sqflite</code>), the documents folder (Android, iOS and the macOS sandbox) and the application support folder are listed without any registration. Pass <code>searchDirectories:</code> to <code>FloconDatabase</code> to scan other folders.</p>

KotlinSwiftFlutter <p>Add the module (the <code>-no-op</code> twin keeps the same API in release builds, see Release builds):</p> <pre><code>dependencies {
    debugImplementation("io.github.openflocon:flocon-deeplinks:LAST_VERSION")
    releaseImplementation("io.github.openflocon:flocon-deeplinks-no-op:LAST_VERSION")
}
</code></pre> <p>Declare the deeplinks and variables when you install the plugin:</p> <pre><code>startFlocon(FloconContext(context)) {
    install(FloconDeeplinks) {
        variable("host") {
            description = "Host scheme/domain"
            autoComplete(listOf("flocon", "myapp"))
        }

        variable("sample_comment")

        deeplink("[host]://home") {
            "host" withVariable "host"
        }

        deeplink("[host]://user/[userId]") {
            label = "User Profile"
            "userId" withAutoComplete listOf("101", "202", "303")
            "host" withVariable "host"
        }

        deeplink("[host]://post/[postId]?comment=[commentText]") {
            label = "Post Detail"
            description = "Opens a post and pre-fills comment text"
            "postId" withAutoComplete listOf("1", "2", "3")
            "commentText" withVariable "sample_comment"
            "host" withVariable "host"
        }
    }
}
</code></pre> <p>Deeplinks are part of the <code>Flocon</code> product. Install the plugin and list the links in its options:</p> <pre><code>import Flocon

#if DEBUG
startFlocon { flocon in
    flocon.install(.deeplinks) { options in
        options.register(
            [
                FloconDeeplink("myapp://home", label: "Home"),
                FloconDeeplink(
                    "myapp://user/[userId]",
                    label: "User",
                    description: "Open the profile of a user",
                    parameters: [.autoComplete("userId", ["Florent", "David"])]
                ),
                FloconDeeplink("myapp://[env]/settings", parameters: [.variable("env", variableName: "env")]),
            ],
            variables: [FloconDeeplinkVariable("env", suggestions: ["staging", "production"])]
        )
    }
}
#endif
</code></pre> <pre><code>flutter pub add flocon
</code></pre> <p>The deeplinks plugin is part of the <code>flocon</code> package and is always available: no <code>install(...)</code> is needed, you only have to start Flocon (see Flutter SDK). Once Flocon is started, list your links:</p> <pre><code>import 'package:flocon/flocon.dart';

Flocon.deeplinks.register(
  [
    FloconDeeplink('myapp://home', label: 'Home'),
    FloconDeeplink(
      'myapp://user/[userId]',
      label: 'User',
      description: 'Open the profile of a user',
      parameters: [FloconDeeplinkParameter.autoComplete('userId', ['Florent', 'David'])],
    ),
    FloconDeeplink('myapp://[env]/settings', parameters: [FloconDeeplinkParameter.variable('env', variableName: 'env')]),
  ],
  variables: [FloconDeeplinkVariable('env', suggestions: ['staging', 'production'])],
);
</code></pre>

KotlinSwiftFlutter <p>Add the module (the <code>-no-op</code> twin keeps the same API in release builds, see Release builds):</p> <pre><code>dependencies {
    debugImplementation("io.github.openflocon:flocon-feature-flags:LAST_VERSION")
    releaseImplementation("io.github.openflocon:flocon-feature-flags-no-op:LAST_VERSION")
}
</code></pre> <p>Install the plugin when you start Flocon:</p> <pre><code>startFlocon(FloconContext(applicationContext)) {
    install(FloconFeatureFlags)
}
</code></pre> <p>Feature flags are part of the <code>Flocon</code> product. Install the plugin:</p> <pre><code>import Flocon

#if DEBUG
startFlocon { flocon in
    flocon.install(.featureFlags)
}
#endif
</code></pre> <p><code>Flocon.initialize()</code> installs every plugin.</p> <pre><code>flutter pub add flocon
</code></pre> <p>The feature flags plugin is part of the <code>flocon</code> package and is always available: no <code>install(...)</code> is needed, you only have to start Flocon (see Flutter SDK). Registering does nothing before Flocon is started, so you can leave the calls in your code.</p> <pre><code>import 'package:flocon/flocon.dart';

await startFlocon((flocon) =&gt; flocon..connect(host: 'localhost'));
</code></pre>

KotlinSwiftFlutter <pre><code>dependencies {
    debugImplementation("io.github.openflocon:flocon-files:LAST_VERSION")
    releaseImplementation("io.github.openflocon:flocon-files-no-op:LAST_VERSION")
}
</code></pre> <pre><code>startFlocon(FloconContext(context)) {
    install(FloconFiles)
}
</code></pre> <p>Files are part of the <code>Flocon</code> product, there is nothing else to add:</p> <pre><code>import Flocon

#if DEBUG
startFlocon { flocon in
    flocon.install(.files)
}
#endif
</code></pre> <p>The files are sent to the desktop over HTTPS, on the HTTP port of the desktop (<code>9024</code> by default), with the same self-signed trust as the WebSocket. On a physical device, the app only needs the local network permission (<code>NSLocalNetworkUsageDescription</code> in <code>Info.plist</code>): no App Transport Security exception is needed.</p> <pre><code>flutter pub add flocon flocon_files
</code></pre> <pre><code>import 'package:flocon/flocon.dart';
import 'package:flocon_files/flocon_files.dart';

await startFlocon((flocon) =&gt; flocon..install(const FloconFiles()));
</code></pre> <p>Downloads are uploaded to the desktop over HTTPS (port <code>9024</code>), streamed.</p>

KotlinSwiftFlutter <p>At install time:</p> <pre><code>startFlocon(FloconContext(context)) {
    install(FloconFiles) {
        folder(
            displayName = "Shared preferences",
            absolutePath = "${context.filesDir.parentFile!!.absolutePath}/shared_prefs",
        )
    }
}
</code></pre> <p>or later, once the plugin is installed:</p> <pre><code>Flocon.filesPlugin.register(displayName = "Exports", absolutePath = exportsDir.absolutePath)
</code></pre> <p>Registering the same folder again replaces its name; registering a default folder renames it. A folder that does not exist is not shown.</p> <p>On iOS, show the container of an App Group shared with your widgets and extensions (the app needs the App Groups capability):</p> <pre><code>Flocon.filesPlugin.registerAppGroup("group.com.example.app")
</code></pre> <p>At install time:</p> <pre><code>#if DEBUG
startFlocon { flocon in
    flocon.install(.files) { options in
        options.folder(displayName: "Exports", url: URL.documentsDirectory.appending(path: "exports"))
        options.appGroup("group.com.example.app")
    }
}
#endif
</code></pre> <p>or later:</p> <pre><code>Flocon.filesPlugin.register(displayName: "Exports", url: exportsURL)
Flocon.filesPlugin.register(displayName: "Exports", absolutePath: exportsPath)
Flocon.filesPlugin.registerAppGroup("group.com.example.app")
</code></pre> <p><code>registerAppGroup(_:)</code> shows the container of an App Group shared with your widgets and extensions, under the name <code>App Group · &lt;identifier&gt;</code>. The app needs the App Groups capability with this identifier, otherwise nothing is shown (with logs enabled, Flocon prints a message). Registering the same folder again renames it.</p> <pre><code>import 'package:flocon/flocon.dart';
import 'package:flocon_files/flocon_files.dart';

Flocon.files.register('Exports', Directory('${docs.path}/exports'));
</code></pre> <p>The plugin must be installed first (the call does nothing before). Registering the same folder again renames it. Pass <code>defaultRoots:</code> to <code>FloconFiles</code> to replace the default folders.</p>

KotlinSwiftFlutter <p>gRPC version</p> <p>Use <code>grpc-android</code> / <code>grpc-java</code> <code>1.70.0</code> or later.</p> <p>gRPC calls are reported to the network plugin: add <code>flocon-network-core</code> (see Network) and install it:</p> <pre><code>startFlocon(FloconContext(context)) {
    install(FloconNetwork)
}
</code></pre> <p>Android projects use either the standard Protobuf runtime or the lite one. Flocon has one artifact for each, to serialise the messages to JSON properly:</p> Protobuf Lite (recommended for Android)Full Protobuf <pre><code>dependencies {
    implementation("com.google.protobuf:protobuf-kotlin-lite:$PROTOBUF_VERSION")

    debugImplementation("io.github.openflocon:flocon-grpc-interceptor-lite:LAST_VERSION")
    releaseImplementation("io.github.openflocon:flocon-grpc-interceptor-lite-no-op:LAST_VERSION")
}
</code></pre> <pre><code>dependencies {
    implementation("com.google.protobuf:protobuf-kotlin:$PROTOBUF_VERSION")

    debugImplementation("io.github.openflocon:flocon-grpc-interceptor:LAST_VERSION")
    releaseImplementation("io.github.openflocon:flocon-grpc-interceptor-no-op:LAST_VERSION")
}
</code></pre> <p>The <code>-no-op</code> artifacts expose the same API (<code>FloconGrpcInterceptor</code>, <code>FloconGrpcFormatter</code>) and forward every call untouched, so the same code compiles in debug and release.</p> <p>gRPC lives in a separate package, <code>FloconSwiftGrpc</code>, so that apps without gRPC do not depend on <code>grpc-swift</code> and SwiftNIO. It needs iOS 15+ or macOS 12+ and <code>grpc-swift</code> 1.26.0 or a later 1.x.</p> <pre><code>dependencies: [
    .package(url: "https://github.com/openflocon/FloconSwiftGrpc.git", from: "LAST_VERSION"),
],
targets: [
    .target(name: "MyApp", dependencies: [
        .product(name: "FloconGrpc", package: "FloconSwiftGrpc"),
    ]),
]
</code></pre> <p><code>FloconGrpc</code> includes the Flocon SDK: <code>import FloconGrpc</code> is enough to start it. The calls are logged through the network plugin, so install it:</p> <pre><code>import FloconGrpc

#if DEBUG
startFlocon { flocon in
    flocon.install(.network)
}
#endif
</code></pre> <p><code>Flocon.initialize()</code> installs every plugin and needs nothing more. The interceptor does nothing until the SDK is started.</p> <p>Not available in the Flutter SDK yet</p> <p>Flutter cannot report gRPC calls.</p>

KotlinSwiftFlutter <p>Attach <code>FloconGrpcInterceptor</code> to your <code>ManagedChannelBuilder</code>:</p> <pre><code>// lite artifact: io.github.openflocon.flocon.grpc.lite.FloconGrpcInterceptor
// full artifact: io.github.openflocon.flocon.grpc.FloconGrpcInterceptor
val channel = ManagedChannelBuilder.forAddress(host, port)
    .intercept(FloconGrpcInterceptor())
    .build()
</code></pre> <p><code>grpc-swift</code> builds the interceptors of each call from the interceptor factory of the generated client. Return a <code>FloconGrpcClientInterceptor</code> for each method:</p> <pre><code>import FloconGrpc
import GRPC

struct GreeterInterceptors: Helloworld_GreeterClientInterceptorFactoryProtocol {
    func makeSayHelloInterceptors() -&gt; [ClientInterceptor&lt;Helloworld_HelloRequest, Helloworld_HelloReply&gt;] {
        [FloconGrpcClientInterceptor(authority: "api.example.com:443")]
    }
}

let client = Helloworld_GreeterAsyncClient(channel: channel, interceptors: GreeterInterceptors())
</code></pre> <p><code>authority</code> is shown as the URL of the calls: an interceptor does not know the channel it runs on.</p> <p>Streaming calls</p> <p>For a streaming call, Flocon shows the first request message and the last response message only.</p> <p>Not available in the Flutter SDK yet</p>

Version catalogBOMPlain Gradle (Android)Kotlin Multiplatform <pre><code>[versions]
flocon = "LAST_VERSION"

[libraries]
flocon = { module = "io.github.openflocon:flocon", version.ref = "flocon" }
flocon-no-op = { module = "io.github.openflocon:flocon-no-op", version.ref = "flocon" }

flocon-network = { module = "io.github.openflocon:flocon-network-core", version.ref = "flocon" }
flocon-network-no-op = { module = "io.github.openflocon:flocon-network-core-no-op", version.ref = "flocon" }
flocon-okhttp = { module = "io.github.openflocon:flocon-okhttp-interceptor", version.ref = "flocon" }
flocon-okhttp-no-op = { module = "io.github.openflocon:flocon-okhttp-interceptor-no-op", version.ref = "flocon" }
flocon-analytics = { module = "io.github.openflocon:flocon-analytics", version.ref = "flocon" }
flocon-analytics-no-op = { module = "io.github.openflocon:flocon-analytics-no-op", version.ref = "flocon" }
# ... one pair per module you use, see the table below
</code></pre> <pre><code>// app/build.gradle.kts
dependencies {
    debugImplementation(libs.flocon)
    releaseImplementation(libs.flocon.no.op)

    debugImplementation(libs.flocon.network)
    releaseImplementation(libs.flocon.network.no.op)
    debugImplementation(libs.flocon.okhttp)
    releaseImplementation(libs.flocon.okhttp.no.op)
    debugImplementation(libs.flocon.analytics)
    releaseImplementation(libs.flocon.analytics.no.op)
}
</code></pre> <p>The <code>flocon-bom</code> pins every Flocon module (and its <code>-no-op</code>) to the same version: declare the version once, then leave the modules without a version.</p> <pre><code>[libraries]
flocon-bom = { module = "io.github.openflocon:flocon-bom", version = "LAST_VERSION" }
flocon = { module = "io.github.openflocon:flocon" }
flocon-no-op = { module = "io.github.openflocon:flocon-no-op" }
flocon-network = { module = "io.github.openflocon:flocon-network-core" }
flocon-network-no-op = { module = "io.github.openflocon:flocon-network-core-no-op" }
</code></pre> <pre><code>dependencies {
    debugImplementation(platform(libs.flocon.bom))
    releaseImplementation(platform(libs.flocon.bom))

    debugImplementation(libs.flocon)
    releaseImplementation(libs.flocon.no.op)

    debugImplementation(libs.flocon.network)
    releaseImplementation(libs.flocon.network.no.op)
}
</code></pre> <pre><code>dependencies {
